// src/cache.js — module-level singleton loaded once
export const cache = new Map();

// test file:
test('A: warms the cache', () => {
  cache.set('k', 1);
  expect(cache.get('k')).toBe(1);
});
test('B: cache starts empty', () => {
  expect(cache.size).toBe(0);
});

Q1: Does B pass when the whole file runs in order? Does B pass when run alone (e.g. with .only)?
Q2: A separate test does setInterval(poll, 1000) and never clears it. What does the runner report at the end, and what's the risk?

